#nullable enable // autogenerated

using MVZ2.Vanilla.Armors;
using MVZ2.Vanilla.Entities;
using PVZEngine;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace MVZ2.Vanilla.Entities
{
    public static class VanillaColliderExt
    {
        public static DamageInput GetDamageInput(this IEntityCollider collider, float amount, DamageEffectList effects, Entity source)
        {
            return new DamageInput(amount, effects, collider.Entity, new EntitySourceReference(source), collider.ArmorSlot);
        }
        public static DamageOutput TakeDamage(this IEntityCollider collider, float amount, DamageEffectList effects, Entity source)
        {
            return collider.TakeDamage(amount, effects, new EntitySourceReference(source));
        }
        public static DamageOutput TakeDamage(this IEntityCollider collider, float amount, DamageEffectList effects, ILevelSourceReference? source)
        {
            return collider.Entity.TakeDamageSourced(amount, effects, source, collider.ArmorSlot);
        }
        public static bool TryDestroyBySpikes(this IEntityCollider collider, Entity source)
        {
            var armorSlot = collider.ArmorSlot;
            var entity = collider.Entity;
            if (!NamespaceID.IsValid(armorSlot))
            {
                return entity.TryDestroyBySpikes(source);
            }
            var armor = entity.GetArmorAtSlot(armorSlot);
            if (armor != null)
            {
                return armor.TryDestroyBySpikes(source);
            }
            return false;
        }
    }
}